-- (TASK-B0420 · المهمّة ٦) الجدولة — للإلغاء: select cron.unschedule('gmt_push_kick'); (وكذا بقيّة الأسماء)
select cron.schedule('gmt_push_kick', '30 seconds', $$select public.gmt_push_kick()$$);
select cron.schedule('gmt_push_version', '*/10 * * * *', $$select net.http_post(url := (select v from public.push_config where k='dispatch_url'), body := '{"job":"version"}'::jsonb, headers := jsonb_build_object('Content-Type','application/json','x-push-secret',(select v from public.push_config where k='cron_secret')), timeout_milliseconds := 10000)$$);
select cron.schedule('gmt_push_aging', '7 7 * * *', $$insert into public.gmt_push_queue(kind, branch_key, topic, data, dedupe_key, send_after) select 'transfer_aging', to_branch, 'pos', jsonb_build_object('n', count(*), 'oldest', min(transfer_number)), 'aging:'||to_branch||':'||current_date, now() from public.branch_stock_transfers where status in ('pending','needs_settlement') and created_at < now() - interval '24 hours' and to_branch is not null group by to_branch on conflict do nothing$$);
select cron.schedule('gmt_push_cleanup', '10 0 * * *', $$delete from public.gmt_push_queue where created_at < now() - interval '30 days'; delete from public.push_rate where at < now() - interval '1 day'; update public.push_subscriptions set disabled_at = now(), disabled_reason = 'stale' where disabled_at is null and last_seen_at < now() - interval '90 days'; delete from public.push_subscriptions where disabled_at < now() - interval '30 days'$$);
